/* Minimal local jsPDF-AutoTable-compatible plugin for SHEARiQ PDF exports. */
(function(global){
  const jsPDF = global.jspdf && global.jspdf.jsPDF;
  if (!jsPDF) return;
  function normalizeHead(head){ return Array.isArray(head) && Array.isArray(head[0]) ? head[0] : (Array.isArray(head) ? head : []); }
  jsPDF.prototype.autoTable = function(options){
    options = options || {};
    const margin = Object.assign({top:12,right:10,bottom:14,left:10}, options.margin || {});
    const startY = Number(options.startY) || margin.top;
    const head = normalizeHead(options.head || []);
    const body = Array.isArray(options.body) ? options.body : [];
    const pageWidth = this.internal.pageSize.getWidth();
    const pageHeight = this.internal.pageSize.getHeight();
    const usableWidth = pageWidth - margin.left - margin.right;
    const columnCount = Math.max(head.length, ...body.map(row => Array.isArray(row) ? row.length : 0), 1);
    const columnWidth = usableWidth / columnCount;
    const fontSize = Number(options.styles && options.styles.fontSize) || 7;
    const cellPad = 1.4;
    let y = startY;
    const drawRow = (row, isHead) => {
      const linesByCell = [];
      let rowHeight = fontSize * 0.55 + cellPad * 2;
      for (let i = 0; i < columnCount; i += 1) {
        const lines = this.splitTextToSize(row[i] == null ? '' : String(row[i]), columnWidth - cellPad * 2);
        linesByCell.push(lines);
        rowHeight = Math.max(rowHeight, lines.length * fontSize * 0.45 + cellPad * 2);
      }
      if (y + rowHeight > pageHeight - margin.bottom) {
        this.addPage();
        y = margin.top;
        if (!isHead && head.length) drawRow(head, true);
      }
      this.setFont('helvetica', isHead ? 'bold' : 'normal');
      this.setFontSize(fontSize);
      this.setTextColor(isHead ? 31 : 17, isHead ? 41 : 24, isHead ? 55 : 39);
      for (let i = 0; i < columnCount; i += 1) {
        this.text(linesByCell[i], margin.left + i * columnWidth + cellPad, y + cellPad + fontSize * 0.35);
      }
      this.setDrawColor(210, 214, 220);
      this.line(margin.left, y + rowHeight, pageWidth - margin.right, y + rowHeight);
      y += rowHeight;
    };
    if (head.length) drawRow(head, true);
    if (body.length) body.forEach(row => drawRow(Array.isArray(row) ? row : [row], false));
    this.lastAutoTable = { finalY: y };
    return this;
  };
})(typeof window !== 'undefined' ? window : this);
